// Adapter: the rule below is the same JavaScript as the recipe's n8n build.
// $('Step name') answers from this step's inputs: each is that step's output in this scenario.
const SOURCES = {"Config": "in0_Config", "Step 9: Read the chair's decisions": "in1_Step9Readthechairsdecisi"};
const LISTS = [];
const EXECUTED = [];
const DATA = {};
for (const [node, key] of Object.entries(SOURCES)) {
  const raw = input[key];
  let v = raw;
  if (typeof raw === 'string') { try { v = JSON.parse(raw); } catch (e) { v = raw; } }
  DATA[node] = LISTS.includes(node) ? (v || []).map(i => (i && i.json !== undefined ? i : { json: i })) : [{ json: v }];
}
const $ = (node) => {
  const ran = node in DATA || EXECUTED.includes(node);
  const list = () => { if (!(node in DATA)) throw new Error(`step ${node} has no data in this scenario`); return DATA[node]; };
  return { isExecuted: ran, first: () => list()[0], last: () => list()[list().length - 1], all: () => list(),
           get item() { return list()[0]; } };
};
const INPUT = "Step 9: Read the chair's decisions";
const $input = { all: () => $(INPUT).all(), first: () => $(INPUT).first(), last: () => $(INPUT).last(), get item() { return $(INPUT).first(); } };
const $execution = { id: input.run_id };
const BODIES = (out) => ({"task_q": encodeURIComponent(out.task_id), "verify_body": JSON.stringify({ verified_date: out.new_date, last_due_seen: out.new_date, changes: 0 }), "log_body": JSON.stringify({ recipe: 'R14.3', item: out.task_id, decision: 'new date verified', rules: { meeting: out.meeting_id, verified_date: out.new_date } }), "failed_body": JSON.stringify({ recipe: 'R14.3', item: out.task_id, reason: 'write failed', detail: 'Verified-date write failed; never retried', owner: $('Config').first().json.exception_owner })});
const one = (r) => (Array.isArray(r) ? r : [r]).filter(Boolean).map(i => (i.json !== undefined ? i.json : i));
const $json = INPUT && INPUT in DATA ? $input.first().json : {};
const __rule = () => {
// Step 9: a new date the chair decided becomes the verified date and resets the change count.
const isDate = d => /^\d{4}-\d{2}-\d{2}$/.test(d || '') && !isNaN(Date.parse(d + 'T00:00:00Z'));
const rows = ($('Step 9: Read the chair\'s decisions').first().json.items || []).filter(a => a.decision === 'new date' && isDate(a.new_date));
return rows.map(a => ({ json: { task_id: a.task_id, new_date: a.new_date, agenda_item_id: a.id, meeting_id: a.meeting_id } }));
};
return { items: one(__rule()).map(o => Object.assign({}, o, BODIES(o))) };
